<?php require_once __DIR__.'/config/constants.php';$rows=db()->query("SELECT c.*,(SELECT COUNT(*) FROM tbl_food f WHERE f.category_id=c.id AND f.active='Yes') food_count FROM tbl_category c WHERE c.active='Yes' ORDER BY c.title")->fetchAll();$pageTitle='Categories — '.APP_NAME;include __DIR__.'/partials-font/menu.php';?><section class="page-hero"><div class="container"><h1>Food Categories</h1><p>Browse the menu by category.</p></div></section><section class="section"><div class="container"><div class="grid grid-4"><?php foreach($rows as $c):?><a class="category-card" href="<?= e(url('foods.php?category='.$c['id'])) ?>"><img src="<?= e(category_image($c['image_name'])) ?>" alt="<?= e($c['title']) ?>"><div class="overlay"><?= e($c['title']) ?> <small>• <?= (int)$c['food_count'] ?> items</small></div></a><?php endforeach;?></div></div></section><?php include __DIR__.'/partials-font/footer.php';?>